onChange:
{(e) => {
                            const v = e.target.value;
                            handleAssign(key, v === "" ? null : Number(v));
                          }}

nonOptionChildren.text:
{contacts.map((c) => {
            const name = c.display_name || `${c.surname ?? ""} ${c.given_name ?? ""}`.trim() || `#${c.id}`;
            return (
              <option key={c.id} value={String(c.id)}>
                {name}
              </option>
            );
          })}

onChange:
{(e) => {
            const v = e.target.value;
            handleCardFieldChange("competitor_check", v === "" ? null : v === "true");
            setTimeout(handleCardFieldBlur, 0);
          }}
